window.bookSummaryJSON = "<p><b>Features three novellas in the enthralling Dark Kings world by </b><b><i>New York Times</i></b><b> best-selling author Donna Grant.</b><br> <i><br> Whisky and Wishes</i></p> <p>Finally free of the dangers surrounding him and the burden of pining after his mate, the King of Dragon Kings is ready for some peace - time to enjoy the woman he loves without interruption.<br> <br> <i>Heart of Gold</i> </p> <p>He’s loved her for eons, wanted her forever, and a day never passes without her at the forefront of his mind.</p> <p><i>Of Fire and Flame</i></p> <p>Three extraordinary beings, one tangled fate.</p>"; 
